TRANSMISSION_NUMBER_RANGE = (1, 9999)
EXTRA_DELAY_RANGE = (1, 50)
def in_range(value, bounds):
    low, high = bounds
    return low <= value <= high


def distinct(numbers):
    return len(set(numbers)) == len(numbers)


